Insert the node "Code - Normalize LinkedIn Jobs" of type "n8n-nodes-base.code" between "Apify - Scrape LinkedIn Jobs" and "Merge - Combine All Sources". Set parameters to: {"jsCode": "// Normalize LinkedIn Jobs data
const jobs = $input.all();
const companyData = $('Google Sheets - Get Target Companies').first().json;
const runDate = $('Set Configuration').first().json.runDate;

return jobs.map(job => ({
  json: {
    source: 'LinkedIn',
    title: job.json.title || '',
    company: job.json.companyName || job.json.company || '',
    location: job.json.location || '',
    description: job.json.description || '',
    postedAt: job.json.postedAt || job.json.listedAt || '',
    applyLink: job.json.applyUrl || job.json.link || '',
    salary: job.json.salary || '',
    targetCompany: companyData['Company Name'] || '',
    targetKeywords: companyData['Target Keywords'] || '',
    mySolution: companyData['My Solution'] || '',
    scrapedDate: runDate,
    jobId: `linkedin-${job.json.title}-${job.json.companyName}`.replace(/\s+/g, '-').toLowerCase().substring(0, 100)
  }
}));"}.

Insert the node "Order Handling" of type "n8n-nodes-base.code" between "Get Low Stock Product" and "Generate Email & PO". Set parameters to: {"jsCode": "const results = [];

for (const item of items) {
  const sku = item.json.sku;
  const name = item.json.Name;
  const supplier = item.json.supplier;
  const supplierEmail = item.json.supplier_email;

  const available = Number(item.json["Available Qty"]) || 0;
  const threshold = Number(item.json["Min. Threshold"]) || 0;
  const minOrder = Number(item.json["Min Order"]) || 0;
  const maxOrder = Number(item.json["Max Order"]) || 0;

  let reorderNeeded = false;
  let orderQty = 0;

  // Check if reorder needed
  if (available < threshold) {
    reorderNeeded = true;

    // Basic calculation: how much short
    orderQty = threshold - available;

    // Ensure reorderQty >= Min Order
    if (orderQty < minOrder) {
      orderQty = minOrder;
    }

    // Ensure reorderQty <= Max Order
    if (orderQty > maxOrder) {
      orderQty = maxOrder;
    }
  }

  results.push({
    json: {
      sku,
      name,
      supplier,
      supplier_email: supplierEmail,
      available,
      threshold,
      minOrder,
      maxOrder,
      reorder_needed: reorderNeeded,
      order_qty: orderQty
    }
  });
}

return results;
"}.
